import { log } from "../log.js";
import { isNeonApiError, messageFromBody } from "../api.js";
import { sendError } from "../analytics.js";
import { writer } from "../writer.js";
import { branchIdFromProps, listAllProjectBranches } from "../utils/enrichers.js";
import { parsePointInTime } from "../utils/point_in_time.js";
import chalk from "chalk";
import { createPatch } from "diff";
//#region src/commands/schema_diff.ts
const COLORS = {
	added: chalk.green,
	removed: chalk.red,
	header: chalk.yellow,
	section: chalk.magenta
};
const schemaDiff = async (props) => {
	props.branch = props.baseBranch || props.branch;
	const baseBranch = await branchIdFromProps(props);
	let pointInTime = await parsePointInTime({
		pointInTime: props.compareSource,
		targetBranchId: baseBranch,
		projectId: props.projectId,
		api: props.apiClient
	});
	const comparingWithParent = props.compareSource.startsWith("^parent");
	let baseBranchPoint = {
		branchId: baseBranch,
		tag: "head"
	};
	[baseBranchPoint, pointInTime] = comparingWithParent ? [pointInTime, baseBranchPoint] : [baseBranchPoint, pointInTime];
	const baseDatabases = await fetchDatabases(baseBranch, props);
	if (props.database) {
		const database = baseDatabases.find((db) => db.name === props.database);
		if (!database) throw new Error(`Database ${props.database} does not exist in base branch ${baseBranch}`);
		const patch = await createSchemaDiff(baseBranchPoint, pointInTime, database, props);
		writer(props).text(colorize(patch));
		return;
	}
	await Promise.all(baseDatabases.map(async (database) => {
		const patch = await createSchemaDiff(baseBranchPoint, pointInTime, database, props);
		writer(props).text(colorize(patch));
	}));
};
const fetchDatabases = async (branch, props) => {
	return props.apiClient.listProjectBranchDatabases(props.projectId, branch).then((response) => response.data.databases);
};
const createSchemaDiff = async (baseBranch, pointInTime, database, props) => {
	const [baseSchema, compareSchema] = await Promise.all([fetchSchema(baseBranch, database, props), fetchSchema(pointInTime, database, props)]);
	return createPatch(`Database: ${database.name}`, baseSchema, compareSchema, generateHeader(baseBranch), generateHeader(pointInTime));
};
const fetchSchema = async (pointInTime, database, props) => {
	try {
		return (await props.apiClient.getProjectBranchSchema({
			projectId: props.projectId,
			branchId: pointInTime.branchId,
			db_name: database.name,
			...pointInTimeParams(pointInTime)
		})).data.sql ?? "";
	} catch (error) {
		if (isNeonApiError(error)) {
			sendError(error, "API_ERROR");
			throw new Error(messageFromBody(error.data) ?? `Error while fetching schema for branch ${pointInTime.branchId}`);
		}
		throw error;
	}
};
const colorize = (patch) => {
	return patch.replace(/^([^\n]+)\n([^\n]+)\n/m, "").replace(/^-.*/gm, colorizer("removed")).replace(/^\+.*/gm, colorizer("added")).replace(/^@@.+@@.*/gm, colorizer("section"));
};
const colorizer = (colorId) => {
	const color = COLORS[colorId];
	return (line) => color(line);
};
const pointInTimeParams = (pointInTime) => {
	switch (pointInTime.tag) {
		case "timestamp": return { timestamp: pointInTime.timestamp };
		case "lsn": return { lsn: pointInTime.lsn ?? void 0 };
		default: return {};
	}
};
const generateHeader = (pointInTime) => {
	const header = `(Branch: ${pointInTime.branchId}`;
	switch (pointInTime.tag) {
		case "timestamp": return `${header} at ${pointInTime.timestamp})`;
		case "lsn": return `${header} at ${pointInTime.lsn})`;
		default: return `${header})`;
	}
};
const parseSchemaDiffParams = async (props) => {
	if (!props.compareSource) {
		if (props.baseBranch) {
			props.compareSource = props.baseBranch;
			props.baseBranch = props.branch;
		} else if (props.branch) {
			if ((await listAllProjectBranches(props.apiClient, props.projectId)).find((b) => b.id === props.branch || b.name === props.branch)?.parent_id == void 0) throw new Error(`No branch specified. Your context branch (${props.branch}) has no parent, so no comparison is possible.`);
			log.info(`No branches specified. Comparing your context branch '${props.branch}' with its parent`);
			props.compareSource = "^parent";
		} else {
			if ((await listAllProjectBranches(props.apiClient, props.projectId)).find((b) => b.default)?.parent_id == void 0) throw new Error("No branch specified. Include a base branch or add a set-context branch to continue. Your default branch has no parent, so no comparison is possible.");
			log.info(`No branches specified. Comparing default branch with its parent`);
			props.compareSource = "^parent";
		}
	}
	return props;
};
//#endregion
export { parseSchemaDiffParams, schemaDiff };
